// Décode le payload base64url et génère le HTML du formulaire
// Affiche : résumé IA + description complète repliable + questions cochables + champ libre
// Transmet (via hidden fields) : ticketSummary, aiSummary, originalQuestions, description
// → permet de stocker l'historique complet à la soumission

const config = $('Set: Form Config').first().json;
const dataParam = $('Webhook: Show Form').first().json.query?.data || '';

let payload;
try {
  if (!dataParam) throw new Error('data param missing');
  let b64 = dataParam.replace(/-/g, '+').replace(/_/g, '/');
  while (b64.length % 4 !== 0) b64 += '=';
  const decoded = Buffer.from(b64, 'base64').toString('utf-8');
  payload = JSON.parse(decoded);
} catch (e) {
  const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><title>Lien invalide</title></head><body style="font-family:sans-serif;padding:40px;text-align:center"><h1>Lien invalide</h1><p>Le paramètre <code>?data=...</code> est manquant ou corrompu (${e.message}).</p><p>Retourne dans ton mail et reclique sur le bouton.</p></body></html>`;
  return [{ json: { html, contentType: 'text/html' } }];
}

const ticketKey = payload.k;
const ticketSummary = payload.s;
const reporterId = payload.r;
const reporterName = payload.rn;
const questions = payload.q || [];
const aiSummary = payload.sm || '';
const description = payload.d || '';
const submitUrl = config.submitUrl;
const jiraDomain = config.jiraDomain;

const escape = (s) => String(s)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;')
  .replace(/'/g, '&#39;');

const questionsHtml = questions.map((q, i) => `
  <label class="question">
    <input type="checkbox" name="q${i}" value="${escape(q)}" checked>
    <span>${escape(q)}</span>
  </label>
`).join('');

const summaryBlock = aiSummary ? `
  <div class="summary-block">
    <div class="block-label">Résumé IA</div>
    <div class="summary">${escape(aiSummary).replace(/\n/g, '<br>')}</div>
  </div>` : '';

const descriptionBlock = description ? `
  <details class="desc-details">
    <summary>📄 Voir la description complète du ticket</summary>
    <div class="desc-content">${escape(description).replace(/\n/g, '<br>')}</div>
  </details>` : '';

const html = `<!DOCTYPE html>
<html lang="fr">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Questions de cadrage — ${escape(ticketKey)}</title>
  <style>
    * { box-sizing: border-box; }
    body {
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
      background: #f4f5f7;
      color: #172b4d;
      margin: 0;
      padding: 40px 20px;
      line-height: 1.5;
    }
    .container {
      max-width: 720px;
      margin: 0 auto;
      background: #fff;
      border-radius: 12px;
      box-shadow: 0 2px 8px rgba(9,30,66,0.08);
      overflow: hidden;
    }
    .header {
      background: linear-gradient(135deg, #0052cc 0%, #0747a6 100%);
      color: #fff;
      padding: 32px 40px;
    }
    .ticket-key {
      display: inline-block;
      background: rgba(255,255,255,0.2);
      padding: 4px 10px;
      border-radius: 4px;
      font-size: 13px;
      font-weight: 600;
      letter-spacing: 0.5px;
      margin-bottom: 12px;
    }
    .header h1 {
      margin: 0;
      font-size: 22px;
      font-weight: 600;
      line-height: 1.3;
    }
    .header .reporter {
      margin-top: 12px;
      font-size: 14px;
      opacity: 0.9;
    }
    .body { padding: 32px 40px; }
    .body h2 {
      margin: 0 0 8px;
      font-size: 16px;
      font-weight: 600;
      color: #172b4d;
    }
    .body .subtitle {
      color: #5e6c84;
      font-size: 14px;
      margin: 0 0 24px;
    }
    .block-label {
      font-size: 12px;
      text-transform: uppercase;
      color: #5e6c84;
      letter-spacing: 0.5px;
      margin-bottom: 8px;
      font-weight: 600;
    }
    .summary-block { margin-bottom: 20px; }
    .summary {
      background: #e9f2ff;
      border-left: 3px solid #0052cc;
      padding: 14px 16px;
      border-radius: 4px;
      font-size: 14px;
      line-height: 1.6;
      color: #172b4d;
    }
    .desc-details {
      background: #f4f5f7;
      border-radius: 6px;
      margin-bottom: 28px;
    }
    .desc-details summary {
      cursor: pointer;
      padding: 12px 16px;
      font-size: 13px;
      font-weight: 600;
      color: #5e6c84;
      text-transform: uppercase;
      letter-spacing: 0.5px;
      list-style: none;
      user-select: none;
    }
    .desc-details summary::-webkit-details-marker { display: none; }
    .desc-details summary::before {
      content: "▸ ";
      display: inline-block;
      transition: transform 0.15s;
    }
    .desc-details[open] summary::before { content: "▾ "; }
    .desc-content {
      padding: 0 16px 16px;
      font-size: 14px;
      line-height: 1.6;
      color: #172b4d;
    }
    .question {
      display: flex;
      gap: 12px;
      align-items: flex-start;
      padding: 14px 16px;
      margin-bottom: 10px;
      background: #f4f5f7;
      border: 1px solid transparent;
      border-radius: 8px;
      cursor: pointer;
      transition: all 0.15s;
    }
    .question:hover {
      background: #ebecf0;
      border-color: #dfe1e6;
    }
    .question input {
      margin: 4px 0 0;
      width: 18px;
      height: 18px;
      accent-color: #0052cc;
      cursor: pointer;
      flex-shrink: 0;
    }
    .question span {
      flex: 1;
      font-size: 14px;
      color: #172b4d;
    }
    .custom-block {
      margin-top: 28px;
      padding-top: 24px;
      border-top: 1px solid #ebecf0;
    }
    textarea {
      width: 100%;
      min-height: 100px;
      padding: 12px;
      border: 1px solid #dfe1e6;
      border-radius: 6px;
      font-family: inherit;
      font-size: 14px;
      color: #172b4d;
      resize: vertical;
      transition: border-color 0.15s;
    }
    textarea:focus {
      outline: none;
      border-color: #0052cc;
      box-shadow: 0 0 0 2px rgba(0,82,204,0.2);
    }
    .actions {
      margin-top: 28px;
      text-align: right;
    }
    button {
      background: #0052cc;
      color: #fff;
      border: 0;
      padding: 12px 28px;
      border-radius: 6px;
      font-size: 15px;
      font-weight: 600;
      cursor: pointer;
      transition: background 0.15s;
    }
    button:hover { background: #0747a6; }
    @media (max-width: 600px) {
      body { padding: 0; }
      .container { border-radius: 0; box-shadow: none; }
      .header, .body { padding: 24px 20px; }
      .actions { text-align: stretch; }
      button { width: 100%; }
    }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <span class="ticket-key">${escape(ticketKey)}</span>
      <h1>${escape(ticketSummary)}</h1>
      <div class="reporter">Demandé par ${escape(reporterName)}</div>
    </div>
    <div class="body">
      ${summaryBlock}
      ${descriptionBlock}

      <form action="${submitUrl}" method="POST">
        <input type="hidden" name="ticketKey" value="${escape(ticketKey)}">
        <input type="hidden" name="ticketSummary" value="${escape(ticketSummary)}">
        <input type="hidden" name="reporterId" value="${escape(reporterId)}">
        <input type="hidden" name="reporterName" value="${escape(reporterName)}">
        <input type="hidden" name="aiSummary" value="${escape(aiSummary)}">
        <input type="hidden" name="ticketDescription" value="${escape(description)}">
        <input type="hidden" name="originalQuestionsJson" value="${escape(JSON.stringify(questions))}">

        <h2>Questions de cadrage proposées</h2>
        <p class="subtitle">Décoche celles que tu ne veux pas envoyer au rapporteur.</p>
        ${questionsHtml}

        <div class="custom-block">
          <h2>Tes propres questions</h2>
          <p class="subtitle">Une par ligne. Elles seront ajoutées à la fin de la liste.</p>
          <textarea name="custom" placeholder="Ex : Y a-t-il des contraintes RGPD spécifiques ?"></textarea>
        </div>

        <div class="actions">
          <button type="submit">Envoyer le commentaire sur Jira →</button>
        </div>
      </form>
    </div>
  </div>
</body>
</html>`;

return [{ json: { html, contentType: 'text/html' } }];

// Lit les champs du formulaire, calcule selected/rejected/custom et construit le payload ADF.

const data = $input.first().json.body || {};

const ticketKey = data.ticketKey;
const ticketSummary = data.ticketSummary || '';
const reporterId = data.reporterId;
const reporterName = data.reporterName || "l'équipe";
const aiSummary = data.aiSummary || '';
const ticketDescription = data.ticketDescription || '';

// Récupère toutes les questions cochées (q0, q1, q2...)
const selectedQuestions = [];
Object.keys(data).forEach(key => {
  if (/^q\d+$/.test(key) && data[key]) {
    selectedQuestions.push(data[key]);
  }
});

// Parse les questions originales (proposées par l'IA, JSON-encodées en hidden field)
let originalQuestions = [];
try {
  originalQuestions = JSON.parse(data.originalQuestionsJson || '[]');
} catch (e) {
  originalQuestions = [];
}

// Calcul des questions rejetées (proposées par l'IA mais décochées)
const rejectedQuestions = originalQuestions.filter(q => !selectedQuestions.includes(q));

// Parse les questions custom (une par ligne)
const customRaw = data.custom || '';
const customQuestions = customRaw
  .split(/\r?\n/)
  .map(s => s.trim())
  .filter(s => s.length > 0);

const allQuestions = [...selectedQuestions, ...customQuestions];

const jiraDomain = $('Set: Form Config').first().json.jiraDomain;

if (allQuestions.length === 0) {
  return [{
    json: {
      ticketKey,
      ticketSummary,
      skipPost: true,
      errorMessage: 'Aucune question sélectionnée — rien à poster.',
      issueViewUrl: `${jiraDomain}/browse/${ticketKey}`,
    }
  }];
}

// Construction du document ADF pour Jira
const introContent = [{ type: 'text', text: 'Hello ' }];
if (reporterId) {
  introContent.push({
    type: 'mention',
    attrs: { id: reporterId, text: '@' + reporterName }
  });
} else {
  introContent.push({ type: 'text', text: '@' + reporterName });
}
introContent.push({
  type: 'text',
  text: ', avant de lancer le ticket voici mes quelques questions :'
});

const listItems = allQuestions.map(q => ({
  type: 'listItem',
  content: [
    { type: 'paragraph', content: [{ type: 'text', text: q }] }
  ]
}));

const adfBody = {
  body: {
    type: 'doc',
    version: 1,
    content: [
      { type: 'paragraph', content: introContent },
      { type: 'bulletList', content: listItems }
    ]
  }
};

return [{
  json: {
    // Pour le node Jira: Post Comment
    ticketKey,
    skipPost: false,
    jiraUrl: `${jiraDomain}/rest/api/3/issue/${ticketKey}/comment`,
    issueViewUrl: `${jiraDomain}/browse/${ticketKey}`,
    adfBody,
    questionsCount: allQuestions.length,

    // Pour le node Google Sheets et la page de confirmation
    ticketSummary,
    reporterName,
    aiSummary,
    ticketDescription,
    originalQuestions,
    selectedQuestions,
    rejectedQuestions,
    customQuestions,
    submittedAt: new Date().toISOString(),
  }
}];

// Page de confirmation après succès — lit les données depuis le webhook directement
// (le node Jira: Post Comment a remplacé $json par sa réponse)

const body = $('Webhook: Submit Form').first().json.body || {};
const ticketKey = body.ticketKey;

const checkedCount = Object.keys(body).filter(k => /^q\d+$/.test(k) && body[k]).length;
const customCount = (body.custom || '')
  .split(/\r?\n/)
  .map(s => s.trim())
  .filter(s => s.length > 0).length;
const questionCount = checkedCount + customCount;

const jiraDomain = $('Set: Form Config').first().json.jiraDomain;

const html = `<!DOCTYPE html>
<html lang="fr">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Commentaire posté</title>
  <style>
    body { font-family: -apple-system, system-ui, sans-serif; background: #f4f5f7; color: #172b4d; margin: 0; padding: 60px 20px; text-align: center; }
    .card { max-width: 480px; margin: 0 auto; background: white; border-radius: 12px; padding: 40px 32px; box-shadow: 0 2px 8px rgba(9,30,66,0.08); }
    .check { font-size: 56px; margin-bottom: 16px; }
    h1 { font-size: 22px; margin: 0 0 8px; }
    p { color: #5e6c84; line-height: 1.5; margin: 0 0 24px; }
    a { display: inline-block; background: #0052cc; color: white; text-decoration: none; padding: 12px 24px; border-radius: 6px; font-weight: 600; transition: background 0.15s; }
    a:hover { background: #0747a6; }
  </style>
</head>
<body>
  <div class="card">
    <div class="check">✅</div>
    <h1>C'est posté !</h1>
    <p>${questionCount} question${questionCount > 1 ? 's' : ''} envoyée${questionCount > 1 ? 's' : ''} en commentaire sur <strong>${ticketKey}</strong>.</p>
    <a href="${jiraDomain}/browse/${ticketKey}" target="_blank">Ouvrir le ticket dans Jira →</a>
  </div>
</body>
</html>`;

return [{ json: { html } }];

// Page d'erreur si aucune question sélectionnée
const src = $input.first().json;
const ticketKey = src.ticketKey || '';
const issueUrl = src.issueViewUrl || '#';
const errorMessage = src.errorMessage || 'Tu dois cocher au moins une question (ou en ajouter dans le champ libre) avant de valider.';

const html = `<!DOCTYPE html>
<html lang="fr">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Aucune question</title>
  <style>
    body { font-family: -apple-system, system-ui, sans-serif; background: #f4f5f7; color: #172b4d; margin: 0; padding: 60px 20px; text-align: center; }
    .card { max-width: 480px; margin: 0 auto; background: white; border-radius: 12px; padding: 40px 32px; box-shadow: 0 2px 8px rgba(9,30,66,0.08); }
    .icon { font-size: 56px; margin-bottom: 16px; }
    h1 { margin: 0 0 12px; font-size: 22px; }
    p { color: #5e6c84; line-height: 1.5; margin: 0 0 24px; }
    a { display: inline-block; background: white; color: #0052cc; border: 1px solid #0052cc; padding: 10px 20px; border-radius: 6px; font-weight: 600; text-decoration: none; }
    a:hover { background: #f4f5f7; }
  </style>
</head>
<body>
  <div class="card">
    <div class="icon">⚠️</div>
    <h1>Aucune question sélectionnée</h1>
    <p>${errorMessage}</p>
    <a href="${issueUrl}" target="_blank">Ouvrir ${ticketKey} sur Jira →</a>
  </div>
</body>
</html>`;

return [{ json: { html } }];
